def getFibonacci(n):
    '''
    Compute the n-th fibonacci number using loops only.
    '''
    if n <= 0:
        return None
    elif n == 1 or n == 2:
        return 1

    fib_sequence = [1, 1]
    for i in range(3, n + 1):
        next_fib = fib_sequence[-1] + fib_sequence[-2]
        fib_sequence.append(next_fib)

    return fib_sequence[-1]

